// Last Qualifying Order Date
{ FIXED [Customer ID] : MAX(IF [Order Total] > 0
    THEN [Order Date] END) }

// Purchases Prior 12 Months
{ FIXED [Customer ID] : COUNTD(IF [Order Total] > 0
    AND [Order Date] >= DATEADD('month', -12, [As Of Date])
    AND [Order Date] < [As Of Date]
    THEN [Order ID] END) }
